#[test]
fn test_certified_let() {
    use crate::cert::CertVerifier;

    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // let x : Type := Prop in x
    // x has type Type (declared), and the body x returns x = Prop
    // So the result type is Type (the body's type is Type, substituted with value gives Type)
    let let_expr = Expr::let_named(
        Name::anon(),
        Expr::from_kind(ExprKind::Sort(Level::succ(Level::zero()))), // Type 0
        Expr::prop(),                                                // Prop : Type 0
        Expr::bvar(0),                                               // x
        false,
    );
    let (ty, cert) = tc.infer_type_with_cert(&let_expr).unwrap();

    // Body type (x : Type) gets substituted with value (Prop), so result is Type
    // Actually: body has type Type, and result_type = body_type.instantiate(val)
    // Since body = BVar(0) and body_type = Type (the declared type of x),
    // body_type.instantiate(Prop) = Type (no BVar in Type)
    // So the result type is Type 0
    assert!(ty.is_sort());

    // Verify certificate
    let mut verifier = CertVerifier::new(&env);
    let verified_ty = verifier.verify(&cert, &let_expr).unwrap();
    assert_eq!(ty, verified_ty);
}

/// Regression: dependent Let in cert path must use subst_fvar, not instantiate.
///
/// `let x : Type 1 := Prop in (fun (y : x) => y)` should have cert result_type
/// `Prop → Prop` with no escaped FVars. The old code used `body_type.instantiate(val)`
/// which searched for BVar(0) but found none (open_bvar had already converted to FVars).
#[test]
fn test_certified_dependent_let_no_fvar_escape() {
    use crate::cert::CertVerifier;

    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // let x : Type 1 := Prop in (fun (y : x) => y)
    let inner_lam = Expr::lam(BinderInfo::Default, Expr::bvar(0), Expr::bvar(0));
    let let_expr = Expr::let_named(
        Name::anon(),
        Expr::sort(Level::succ(Level::zero())), // x : Type 1
        Expr::prop(),                           // x := Prop
        inner_lam,
        false,
    );

    let (ty, cert) = tc.infer_type_with_cert(&let_expr).unwrap();

    // Result type must not contain FVars
    assert!(
        !ty.has_fvar_quick(),
        "Certified dependent let type contains escaped FVars: {ty:?}"
    );

    // Should be Pi(Prop, Prop) = Prop → Prop
    match &ty.kind {
        ExprKind::Pi(_bi, domain, body) => {
            assert!(domain.is_prop(), "Expected domain Prop, got {domain:?}");
            assert!(!body.has_fvar_quick(), "Pi body contains FVars: {body:?}");
        }
        _ => panic!("Expected Pi type, got {ty:?}"),
    }

    // Verify certificate
    let mut verifier = CertVerifier::new(&env);
    let verified_ty = verifier.verify(&cert, &let_expr).unwrap();
    assert_eq!(
        ty, verified_ty,
        "Cert verification mismatch for dependent let"
    );
}

