/// Test certificate generation for Proj (structure field projection).
///
/// This was identified as a gap: no test verified that infer_type_with_cert
/// produces and verifies a ProofCert::Proj certificate. The Proj cert records
/// the struct name, field index, inner expression's type, and the projected
/// field type.
#[test]
fn test_certified_proj() {
    use crate::cert::CertVerifier;
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();

    // Define Pair : Type → Type → Type
    let pair = Name::from_string("Pair");
    let pair_type = Expr::pi(
        BinderInfo::Default,
        Expr::type_(),
        Expr::pi(BinderInfo::Default, Expr::type_(), Expr::type_()),
    );

    // Pair.mk : (A B : Type) → A → B → Pair A B
    let mk_type = Expr::pi(
        BinderInfo::Default,
        Expr::type_(), // A
        Expr::pi(
            BinderInfo::Default,
            Expr::type_(), // B
            Expr::pi(
                BinderInfo::Default,
                Expr::bvar(1), // A
                Expr::pi(
                    BinderInfo::Default,
                    Expr::bvar(1), // B
                    Expr::app(
                        Expr::app(Expr::const_(pair.clone(), vec![]), Expr::bvar(3)),
                        Expr::bvar(2),
                    ),
                ),
            ),
        ),
    );

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 2,
        types: vec![InductiveType {
            name: pair.clone(),
            type_: pair_type,
            constructors: vec![Constructor {
                name: Name::from_string("Pair.mk"),
                type_: mk_type,
            }],
        }],
    };
    env.add_inductive(decl).unwrap();

    // Build Pair.mk Prop Prop p q where p, q : Prop
    // Use Prop as both type arguments (Pair Prop Prop)
    let mk = Expr::const_(Name::from_string("Pair.mk"), vec![]);

    // We need actual propositions for the fields
    env.add_decl(crate::env::Declaration::Axiom {
        name: Name::from_string("p"),
        level_params: vec![],
        type_: Expr::prop(),
    })
    .unwrap();
    env.add_decl(crate::env::Declaration::Axiom {
        name: Name::from_string("q"),
        level_params: vec![],
        type_: Expr::prop(),
    })
    .unwrap();

    let tc = TypeChecker::new(&env);

    let p = Expr::const_(Name::from_string("p"), vec![]);
    let q = Expr::const_(Name::from_string("q"), vec![]);

    let pair_val = Expr::app(
        Expr::app(Expr::app(Expr::app(mk, Expr::prop()), Expr::prop()), p),
        q,
    );

    // Proj field 0 from Pair
    let proj0 = Expr::proj(pair.clone(), 0, pair_val.clone());
    let (ty0, cert0) = tc.infer_type_with_cert(&proj0).unwrap();

    // Field 0 should have type Prop (the first type parameter)
    assert!(
        ty0.is_prop(),
        "Projected field 0 should have type Prop, got {ty0:?}"
    );

    // Verify certificate independently
    let mut verifier = CertVerifier::new(&env);
    let verified_ty0 = verifier.verify(&cert0, &proj0).unwrap();
    assert_eq!(
        ty0, verified_ty0,
        "Proj cert verification mismatch for field 0"
    );

    // Also test field 1
    let proj1 = Expr::proj(pair, 1, pair_val);
    let (ty1, cert1) = tc.infer_type_with_cert(&proj1).unwrap();

    assert!(
        ty1.is_prop(),
        "Projected field 1 should have type Prop, got {ty1:?}"
    );

    let verified_ty1 = verifier.verify(&cert1, &proj1).unwrap();
    assert_eq!(
        ty1, verified_ty1,
        "Proj cert verification mismatch for field 1"
    );
}

/// Build a Pair structure environment with axioms p, q : Prop.
///
/// Returns (env, pair_name, pair_val, proj0) where:
/// - Pair : Type → Type → Type with Pair.mk constructor
/// - p, q : Prop are axioms
/// - pair_val = Pair.mk Prop Prop p q
/// - proj0 = pair_val.0
fn setup_pair_env() -> (Environment, Name, Expr, Expr) {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();
    let pair = Name::from_string("Pair");
    let pair_type = Expr::pi(
        BinderInfo::Default,
        Expr::type_(),
        Expr::pi(BinderInfo::Default, Expr::type_(), Expr::type_()),
    );

    let mk_type = Expr::pi(
        BinderInfo::Default,
        Expr::type_(),
        Expr::pi(
            BinderInfo::Default,
            Expr::type_(),
            Expr::pi(
                BinderInfo::Default,
                Expr::bvar(1),
                Expr::pi(
                    BinderInfo::Default,
                    Expr::bvar(1),
                    Expr::app(
                        Expr::app(Expr::const_(pair.clone(), vec![]), Expr::bvar(3)),
                        Expr::bvar(2),
                    ),
                ),
            ),
        ),
    );

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 2,
        types: vec![InductiveType {
            name: pair.clone(),
            type_: pair_type,
            constructors: vec![Constructor {
                name: Name::from_string("Pair.mk"),
                type_: mk_type,
            }],
        }],
    };
    env.add_inductive(decl).unwrap();

    for name in ["p", "q"] {
        env.add_decl(crate::env::Declaration::Axiom {
            name: Name::from_string(name),
            level_params: vec![],
            type_: Expr::prop(),
        })
        .unwrap();
    }

    let mk = Expr::const_(Name::from_string("Pair.mk"), vec![]);
    let p = Expr::const_(Name::from_string("p"), vec![]);
    let q = Expr::const_(Name::from_string("q"), vec![]);
    let pair_val = Expr::app(
        Expr::app(Expr::app(Expr::app(mk, Expr::prop()), Expr::prop()), p),
        q,
    );
    let proj0 = Expr::proj(pair.clone(), 0, pair_val.clone());
    (env, pair, pair_val, proj0)
}

/// Test that the verifier rejects a Proj certificate with a forged field_type.
///
/// Soundness test for #2064: a malicious certificate could previously claim
/// any field_type for a valid projection and the verifier would accept it.
/// After the fix, the verifier independently derives the field_type from the
/// environment's structure definition and rejects mismatches.
#[test]
fn test_certified_proj_rejects_forged_field_type() {
    use crate::cert::{CertError, CertVerifier, ProofCert};

    let (env, _pair, _pair_val, proj0) = setup_pair_env();
    let tc = TypeChecker::new(&env);

    // Get a legitimate certificate for proj 0
    let (_ty0, cert0) = tc.infer_type_with_cert(&proj0).unwrap();

    // Tamper: replace field_type with Nat (wrong type)
    let forged_cert = match cert0 {
        ProofCert::Proj {
            struct_name,
            idx,
            expr_cert,
            expr_type,
            field_type: _,
        } => ProofCert::Proj {
            struct_name,
            idx,
            expr_cert,
            expr_type,
            field_type: Box::new(Expr::const_(Name::from_string("Nat"), vec![])),
        },
        _ => panic!("Expected Proj cert"),
    };

    // Verifier should reject forged certificate
    let mut verifier = CertVerifier::new(&env);
    let result = verifier.verify(&forged_cert, &proj0);
    match result {
        Err(CertError::TypeMismatch { location, .. }) => {
            assert!(
                location.contains("field_type"),
                "Error should mention field_type mismatch, got: {location}"
            );
        }
        Err(other) => panic!("Expected TypeMismatch, got: {other:?}"),
        Ok(_) => panic!("Verifier should reject Proj cert with forged field_type"),
    }

    // Legitimate certificate should still pass
    let (_ty0, legit_cert) = tc.infer_type_with_cert(&proj0).unwrap();
    let mut verifier2 = CertVerifier::new(&env);
    let _ = verifier2
        .verify(&legit_cert, &proj0)
        .expect("Legitimate Proj cert should pass");
}

/// Test that derive_proj_field_type rejects out-of-bounds field indices.
///
/// Adversarial test: forge a Proj cert with idx=5 when the struct only has 2 fields.
/// The verifier must reject this even if the cert claims a plausible field_type.
#[test]
fn test_certified_proj_rejects_oob_index() {
    use crate::cert::{CertError, CertVerifier, ProofCert};

    let (env, pair, pair_val, proj0) = setup_pair_env();
    let tc = TypeChecker::new(&env);

    // Get a legitimate certificate for proj 0
    let (_ty0, cert0) = tc.infer_type_with_cert(&proj0).unwrap();

    // Forge: change idx to 5 (Pair only has 2 fields)
    let forged_cert = match cert0 {
        ProofCert::Proj {
            struct_name,
            idx: _,
            expr_cert,
            expr_type,
            field_type,
        } => ProofCert::Proj {
            struct_name,
            idx: 5,
            expr_cert,
            expr_type,
            field_type,
        },
        _ => panic!("Expected Proj cert"),
    };

    // Also forge the expression to have idx=5
    let forged_proj = Expr::proj(pair, 5, pair_val);

    let mut verifier = CertVerifier::new(&env);
    let result = verifier.verify(&forged_cert, &forged_proj);
    match result {
        Err(CertError::InvalidCert(msg)) => {
            assert!(
                msg.contains("out of bounds"),
                "Error should mention out of bounds, got: {msg}"
            );
        }
        Err(other) => panic!("Expected InvalidCert(out of bounds), got: {other:?}"),
        Ok(_) => panic!("Verifier should reject Proj cert with OOB field index"),
    }
}

/// Test that derive_proj_field_type rejects a non-structure inductive (2+ constructors).
///
/// Adversarial test: build an enum with 2 constructors and try to project from it.
/// The verifier must reject because Proj is only valid for structures (1 constructor).
#[test]
fn test_certified_proj_rejects_non_structure_inductive() {
    use crate::cert::{CertError, CertVerifier, ProofCert};
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();

    // Define MyBool : Type with constructors myTrue, myFalse
    let mybool = Name::from_string("MyBool");
    let mybool_type = Expr::type_();

    let true_ctor_type = Expr::const_(mybool.clone(), vec![]);
    let false_ctor_type = Expr::const_(mybool.clone(), vec![]);

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: mybool.clone(),
            type_: mybool_type,
            constructors: vec![
                Constructor {
                    name: Name::from_string("MyBool.myTrue"),
                    type_: true_ctor_type,
                },
                Constructor {
                    name: Name::from_string("MyBool.myFalse"),
                    type_: false_ctor_type,
                },
            ],
        }],
    };
    env.add_inductive(decl).unwrap();

    // Add an axiom b : MyBool
    env.add_decl(crate::env::Declaration::Axiom {
        name: Name::from_string("b"),
        level_params: vec![],
        type_: Expr::const_(mybool.clone(), vec![]),
    })
    .unwrap();

    let b = Expr::const_(Name::from_string("b"), vec![]);

    // Forge a Proj cert for MyBool.0 b — this is invalid (MyBool has 2 constructors)
    let forged_proj = Expr::proj(mybool.clone(), 0, b.clone());

    // Build a minimal forged cert (the TC would refuse to generate one)
    let inner_cert = Box::new(ProofCert::Const {
        name: Name::from_string("b"),
        levels: vec![],
        type_: Box::new(Expr::const_(mybool.clone(), vec![])),
    });
    let forged_cert = ProofCert::Proj {
        struct_name: mybool.clone(),
        idx: 0,
        expr_cert: inner_cert,
        expr_type: Box::new(Expr::const_(mybool.clone(), vec![])),
        field_type: Box::new(Expr::prop()), // arbitrary claim
    };

    let mut verifier = CertVerifier::new(&env);
    let result = verifier.verify(&forged_cert, &forged_proj);
    match result {
        Err(CertError::InvalidCert(msg)) => {
            assert!(
                msg.contains("constructors"),
                "Error should mention constructor count, got: {msg}"
            );
        }
        Err(other) => panic!("Expected InvalidCert about constructors, got: {other:?}"),
        Ok(_) => panic!("Verifier should reject Proj on non-structure (2 constructors)"),
    }
}

/// Test that derive_proj_field_type rejects struct name mismatch between cert and type.
///
/// Adversarial test: the cert claims struct_name is "Fake" but the expression's actual
/// inferred type is Pair Prop Prop. The verifier must detect the mismatch.
#[test]
fn test_certified_proj_rejects_struct_name_mismatch() {
    use crate::cert::{CertVerifier, ProofCert};

    let (env, _pair, _pair_val, proj0) = setup_pair_env();
    let tc = TypeChecker::new(&env);

    // Get a legitimate certificate for proj 0
    let (_ty0, cert0) = tc.infer_type_with_cert(&proj0).unwrap();

    // Forge: change struct_name to "Fake"
    let forged_cert = match cert0 {
        ProofCert::Proj {
            struct_name: _,
            idx,
            expr_cert,
            expr_type,
            field_type,
        } => ProofCert::Proj {
            struct_name: Name::from_string("Fake"),
            idx,
            expr_cert,
            expr_type,
            field_type,
        },
        _ => panic!("Expected Proj cert"),
    };

    // Also forge the expression to claim "Fake" struct
    let forged_proj = Expr::proj(Name::from_string("Fake"), 0, {
        let mk = Expr::const_(Name::from_string("Pair.mk"), vec![]);
        let p = Expr::const_(Name::from_string("p"), vec![]);
        let q = Expr::const_(Name::from_string("q"), vec![]);
        Expr::app(
            Expr::app(Expr::app(Expr::app(mk, Expr::prop()), Expr::prop()), p),
            q,
        )
    });

    let mut verifier = CertVerifier::new(&env);
    let result = verifier.verify(&forged_cert, &forged_proj);
    // Should fail because derive_proj_field_type sees the expression's type is
    // Pair Prop Prop but the cert claims struct_name "Fake"
    assert!(
        result.is_err(),
        "Verifier should reject Proj cert with mismatched struct_name"
    );
}

/// Build a Dep : Type 1 environment with a dependent second field.
/// Dep.mk : (fst : Type) → (snd : fst) → Dep
/// Returns (env, dep_name, d_const, proj1_expr).
fn setup_dep_env() -> (Environment, Name, Expr, Expr) {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};
    use crate::level::Level;
    let mut env = Environment::new();
    let dep = Name::from_string("Dep");
    // Pi(Type, Pi(BVar(0), Const(Dep))) — snd's domain BVar(0) references fst
    let mk_type = Expr::pi(
        BinderInfo::Default,
        Expr::type_(),
        Expr::pi(
            BinderInfo::Default,
            Expr::bvar(0),
            Expr::const_(dep.clone(), vec![]),
        ),
    );
    // Field fst : Type (= Sort(1)) requires result at Sort(2) = Type 1
    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 0,
        types: vec![InductiveType {
            name: dep.clone(),
            type_: Expr::sort(Level::succ(Level::succ(Level::zero()))),
            constructors: vec![Constructor {
                name: Name::from_string("Dep.mk"),
                type_: mk_type,
            }],
        }],
    };
    env.add_inductive(decl).unwrap();
    env.add_decl(crate::env::Declaration::Axiom {
        name: Name::from_string("d"),
        level_params: vec![],
        type_: Expr::const_(dep.clone(), vec![]),
    })
    .unwrap();
    let d = Expr::const_(Name::from_string("d"), vec![]);
    let proj1 = Expr::proj(dep.clone(), 1, d.clone());
    (env, dep, d, proj1)
}

/// Helper to build a Proj cert for axiom "d" of type `dep_type`.
fn mk_dep_proj_cert(dep: &Name, idx: u32, field_type: Expr) -> crate::cert::ProofCert {
    use crate::cert::ProofCert;
    let dep_ty = Expr::const_(dep.clone(), vec![]);
    ProofCert::Proj {
        struct_name: dep.clone(),
        idx,
        expr_cert: Box::new(ProofCert::Const {
            name: Name::from_string("d"),
            levels: vec![],
            type_: Box::new(dep_ty.clone()),
        }),
        expr_type: Box::new(dep_ty),
        field_type: Box::new(field_type),
    }
}

/// Adversarial: dependent field forgery. Tests has_loose_bvars branch (cert/mod.rs:1947).
/// Dep.mk has snd : fst (dependent). Forge field_type to Prop; correct is Dep.0 d.
#[test]
fn test_certified_proj_rejects_forged_dependent_field() {
    use crate::cert::{CertError, CertVerifier};
    let (env, dep, d, proj1) = setup_dep_env();

    // Forged: claims field_type is Prop (wrong — should be Dep.0 d)
    let forged = mk_dep_proj_cert(&dep, 1, Expr::prop());
    let mut v = CertVerifier::new(&env);
    match v.verify(&forged, &proj1) {
        Err(CertError::TypeMismatch { location, .. }) => {
            assert!(location.contains("field_type"), "got: {location}");
        }
        Err(other) => panic!("Expected TypeMismatch, got: {other:?}"),
        Ok(_) => panic!("Should reject forged dependent field_type"),
    }

    // Correct: field_type = Dep.0 d (projection substitution for dependent field)
    let correct = mk_dep_proj_cert(&dep, 1, Expr::proj(dep.clone(), 0, d));
    let mut v2 = CertVerifier::new(&env);
    let _ = v2
        .verify(&correct, &proj1)
        .expect("Correct dependent field_type should pass");
}

/// Adversarial: insufficient type arguments. Tests cert/mod.rs:1924 error path.
/// Pair has num_params=2 but expression type has only 1 applied arg.
#[test]
fn test_certified_proj_rejects_insufficient_type_args() {
    use crate::cert::{CertError, CertVerifier, ProofCert};
    let (mut env, pair, _pair_val, _proj0) = setup_pair_env();

    let partial_type = Expr::app(Expr::const_(pair.clone(), vec![]), Expr::prop());
    env.add_decl(crate::env::Declaration::Axiom {
        name: Name::from_string("partial"),
        level_params: vec![],
        type_: partial_type.clone(),
    })
    .unwrap();

    let partial = Expr::const_(Name::from_string("partial"), vec![]);
    let forged_proj = Expr::proj(pair.clone(), 0, partial.clone());
    let forged_cert = ProofCert::Proj {
        struct_name: pair.clone(),
        idx: 0,
        expr_cert: Box::new(ProofCert::Const {
            name: Name::from_string("partial"),
            levels: vec![],
            type_: Box::new(partial_type.clone()),
        }),
        expr_type: Box::new(partial_type),
        field_type: Box::new(Expr::prop()),
    };

    let mut v = CertVerifier::new(&env);
    match v.verify(&forged_cert, &forged_proj) {
        Err(CertError::InvalidCert(msg)) => {
            assert!(msg.contains("not enough type arguments"), "got: {msg}");
        }
        Err(other) => panic!("Expected InvalidCert about type arguments, got: {other:?}"),
        Ok(_) => panic!("Should reject insufficient type arguments"),
    }
}

