/// Test certificate generation for MData (metadata wrapper).
///
/// MData is transparent: its type equals the type of the inner expression.
/// The certificate wraps the inner cert with metadata for traceability.
#[test]
fn test_certified_mdata() {
    use crate::cert::CertVerifier;

    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // MData wrapping Prop — the type should be Sort(1) (same as Prop's type)
    let metadata = vec![(Name::from_string("note"), crate::expr::MDataValue::Nat(0))];
    let mdata_expr = Expr::mdata(metadata, Expr::prop());

    let (ty, cert) = tc.infer_type_with_cert(&mdata_expr).unwrap();

    // Prop : Sort(1)
    assert!(
        ty.is_sort(),
        "MData(Prop) should have type Sort, got {ty:?}"
    );

    // Verify certificate
    let mut verifier = CertVerifier::new(&env);
    let verified_ty = verifier.verify(&cert, &mdata_expr).unwrap();
    assert_eq!(ty, verified_ty, "MData cert verification mismatch");
}

/// Test certificate generation for nested MData (metadata around typed expression).
#[test]
fn test_certified_mdata_nested() {
    use crate::cert::CertVerifier;

    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // MData wrapping (λ x : Prop. x)
    let lam = Expr::lam(BinderInfo::Default, Expr::prop(), Expr::bvar(0));
    let metadata = vec![(
        Name::from_string("tag"),
        crate::expr::MDataValue::String("identity".into()),
    )];
    let mdata_expr = Expr::mdata(metadata, lam);

    let (ty, cert) = tc.infer_type_with_cert(&mdata_expr).unwrap();

    // (λ x : Prop. x) : Prop → Prop
    match &ty.kind {
        ExprKind::Pi(_, arg, ret) => {
            assert!(arg.is_prop(), "Domain should be Prop");
            assert!(ret.is_prop(), "Codomain should be Prop");
        }
        _ => panic!("Expected Pi type, got {ty:?}"),
    }

    // Verify certificate
    let mut verifier = CertVerifier::new(&env);
    let verified_ty = verifier.verify(&cert, &mdata_expr).unwrap();
    assert_eq!(ty, verified_ty, "Nested MData cert verification mismatch");
}

